(1561489, 208049, 35804, '<td valign="top">Matryoshka! I can''t believe I didn''t think of photographing mine for the challenge! They are so much fun to photograph aren''t they? It''s nice to see something a little different in the challenge...love the bright colors.</td>', 'Matryoshka! I can''t believe I didn''t think of photographing mine for the challenge! They are so much fun to photograph aren''t they? It''s nice to see something a little different in the challenge...love the bright colors.', '2005-07-25 12:17:48.000000', NULL, 1),
(1561491, 208303, 30890, '<td valign="top">I like this a lot, but the Health and Safety people may be after you for lack of eye protection</td>', 'I like this a lot, but the Health and Safety people may be after you for lack of eye protection', '2005-07-25 12:17:53.000000', NULL, 1),
(1561498, 206616, 35804, '<td valign="top">Awesome woody picture! Super creative and you''ve actually given woody a bit of soul...nicely done!</td>', 'Awesome woody picture! Super creative and you''ve actually given woody a bit of soul...nicely done!', '2005-07-25 12:20:38.000000', NULL, 1),
(1561501, 205721, 36499, '<td valign="top">great macro and show of textures here. 10</td>', 'great macro and show of textures here. 10', '2005-07-25 12:21:07.000000', NULL, 1),
(1561505, 207980, 38921, '<td valign="top">This photo is lacking contrast and appears flat.  The chair seems to be leaning to the left but I''m not sure if the photo is crooked or if it is the chair so I won''t take off for that. (5)</td>', 'This photo is lacking contrast and appears flat.  The chair seems to be leaning to the left but I''m not sure if the photo is crooked or if it is the chair so I won''t take off for that. (5)', '2005-07-25 12:23:05.000000', NULL, 1),
(1561508, 208518, 36499, '<td valign="top">i love the treatment u did to this(what did u do...i want to do this to some of my photos too but cant figure it out..pm me) u gave an unsightly abandoned building charcter and eye appeal. love it...good luck 10</td>', 'i love the treatment u did to this(what did u do...i want to do this to some of my photos too but cant figure it out..pm me) u gave an unsightly abandoned building charcter and eye appeal. love it...good luck 10', '2005-07-25 12:23:57.000000', NULL, 1),
(1561509, 205721, 35804, '<td valign="top">This is very pretty...I love clover. The light and color are so nice and subtle. The fluffy whitish border treatment is a little odd and really not necessary...this image is just as lovely without it.</td>', 'This is very pretty...I love clover. The light and color are so nice and subtle. The fluffy whitish border treatment is a little odd and really not necessary...this image is just as lovely without it.', '2005-07-25 12:24:32.000000', NULL, 1),
