(1561518, 208518, 34763, '<td valign="top">ready for a troll to jump out of this one ;)</td>', 'ready for a troll to jump out of this one ;)', '2005-07-25 12:29:30.000000', NULL, 1),
(1561519, 208619, 34852, '<td valign="top">Fabulous! I love the composition, colors, everything. 10 from me and good luck!</td>', 'Fabulous! I love the composition, colors, everything. 10 from me and good luck!', '2005-07-25 12:29:47.000000', NULL, 1),
(1561520, 207046, 35804, '<td valign="top">What a lovely mood this image has...one of my top picks...it''s the hat...I love that hat...really nicely done.</td>', 'What a lovely mood this image has...one of my top picks...it''s the hat...I love that hat...really nicely done.', '2005-07-25 12:30:30.000000', NULL, 1),
(1561521, 208145, 36078, '<td valign="top">Alot of people will not remember class of the titans.  I about laughed what butt I have right off.  Gave it a 7.</td>', 'Alot of people will not remember class of the titans.  I about laughed what butt I have right off.  Gave it a 7.', '2005-07-25 12:30:44.000000', NULL, 1),
(1561524, 206295, 38921, '<td valign="top">Looks to be a tad soft but that may be the jpg compression so I won''t deduct for that.  There also appears to be some dust spots (or something) along the right hand side of the photo and in the lower left corner of the cello that detract from the image.  All in all a very nicely composed shot and well light. (7)</td>', 'Looks to be a tad soft but that may be the jpg compression so I won''t deduct for that.  There also appears to be some dust spots (or something) along the right hand side of the photo and in the lower left corner of the cello that detract from the image.  All in all a very nicely composed shot and well light. (7)', '2005-07-25 12:31:15.000000', NULL, 1),
(1561527, 208552, 35804, '<td valign="top">Really pretty light and perfect subject matter...such character and depth...I really like those super subtle greens, just really nice...one of my favorties for the challenge.</td>', 'Really pretty light and perfect subject matter...such character and depth...I really like those super subtle greens, just really nice...one of my favorties for the challenge.', '2005-07-25 12:33:14.000000', NULL, 1),
(1561529, 208335, 15266, '<td valign="top">Potentially a nice shot, but painfully overprocessed.  The lighter color around the bench betrays your use of Burn around the subject.  PS should be used with subtlety to enhance the image, not distract from it.</td>', 'Potentially a nice shot, but painfully overprocessed.  The lighter color around the bench betrays your use of Burn around the subject.  PS should be used with subtlety to enhance the image, not distract from it.', '2005-07-25 12:33:58.000000', NULL, 1),
(1561530, 207427, 35804, '<td valign="top">A really cool abstract...nice and crisp....great tonality and depth...one of my very favorites in the challenge...so simple but very appealing.</td>', 'A really cool abstract...nice and crisp....great tonality and depth...one of my very favorites in the challenge...so simple but very appealing.', '2005-07-25 12:34:22.000000', NULL, 1),
(1561533, 208489, 38921, '<td valign="top">The guitar in the background is a bit ditracting to me.  Perhaps a smaller DOF to isolate the violin (or maybe it is a voila) and slightly blur the guitar would have worked better. That said, I do like the lighting on both instruments (7)</td>', 'The guitar in the background is a bit ditracting to me.  Perhaps a smaller DOF to isolate the violin (or maybe it is a voila) and slightly blur the guitar would have worked better. That said, I do like the lighting on both instruments (7)', '2005-07-25 12:35:17.000000', NULL, 1),
(1561540, 208673, 38921, '<td valign="top">Nice idea, I think perhaps less posed subject would have proven to be more interesting here. (6)</td>', 'Nice idea, I think perhaps less posed subject would have proven to be more interesting here. (6)', '2005-07-25 12:40:58.000000', NULL, 1),
(1561558, 208180, 40386, '<td valign="top">The whole picture appears to be out of focus.  If you had mounted your camera on a tripod and used the timer you would have avoided the camera shake.</td>', 'The whole picture appears to be out of focus.  If you had mounted your camera on a tripod and used the timer you would have avoided the camera shake.', '2005-07-25 12:56:12.000000', NULL, 1),
(1561562, 208686, 40386, '<td valign="top">A bit of fill flash would have brightened this up nicely so that the grain and knots etc. could be seen more clearly.  It might brighten up a bit in Photoshop or whatever editing package you use but then the background will blow out so probably would have been better to go with my first suggestion so that the branch and background were closer to the same exposure.</td>', 'A bit of fill flash would have brightened this up nicely so that the grain and knots etc. could be seen more clearly.  It might brighten up a bit in Photoshop or whatever editing package you use but then the background will blow out so probably would have been better to go with my first suggestion so that the branch and background were closer to the same exposure.', '2005-07-25 12:59:04.000000', NULL, 1),
(1561588, 208575, 15711, '<td valign="top">I like the simplicity of this. The detailing and light is nice.  This is one of those times when a dead on shot is ok.   You chose a perfect use of shadow and the red filter is appropos.</td>', 'I like the simplicity of this. The detailing and light is nice.  This is one of those times when a dead on shot is ok.   You chose a perfect use of shadow and the red filter is appropos.', '2005-07-25 13:16:37.000000', NULL, 1),
(1561593, 207998, 3569, '<td valign="top">has to be Washington state</td>', 'has to be Washington state', '2005-07-25 13:19:19.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1561594, 207368, 15711, '<td valign="top">He fits right in there perfectly. The tree envelopes him like a glove.   Nice contrasting colors. The overall lighting suits the photo quite well.  I like your imaginative take on the challenge.</td>', 'He fits right in there perfectly. The tree envelopes him like a glove.   Nice contrasting colors. The overall lighting suits the photo quite well.  I like your imaginative take on the challenge.', '2005-07-25 13:19:59.000000', NULL, 1),
(1561595, 208088, 3569, '<td valign="top">a bit too dark, wonderful otherwise</td>', 'a bit too dark, wonderful otherwise', '2005-07-25 13:19:59.000000', NULL, 1),
(1561598, 208560, 15711, '<td valign="top">Oh this is the BEST of the challenge.  So innovative.  Bravo for your creativity. The sepia and single sat is perfect.  The intensity in his face is brilliant.  Kudos to your imaginative take. TEN!!! P.S. The title is just super!!</td>', 'Oh this is the BEST of the challenge.  So innovative.  Bravo for your creativity. The sepia and single sat is perfect.  The intensity in his face is brilliant.  Kudos to your imaginative take. TEN!!! P.S. The title is just super!!', '2005-07-25 13:20:49.000000', NULL, 1),
(1561599, 206144, 15711, '<td valign="top">I think this is superb. A true stand out in this challenge.  It is not only creative, but visually appealing on so many levels. The rounded corners of the chairs amidst the straight lines of the planks makes for a very artful piece.  The lighting and shadow is excellent. I have to give this one a perfect score!! P.S. I love the title as well.</td>', 'I think this is superb. A true stand out in this challenge.  It is not only creative, but visually appealing on so many levels. The rounded corners of the chairs amidst the straight lines of the planks makes for a very artful piece.  The lighting and shadow is excellent. I have to give this one a perfect score!! P.S. I love the title as well.', '2005-07-25 13:21:16.000000', NULL, 1),
(1561601, 207849, 15711, '<td valign="top">Excellent use of sepia.  I love everything about this shot.  It is elegant in it''s simplicity. Perfect angle to the capture.  Really awesome.  I''m giving this a perfect score.  It is well deserved.</td>', 'Excellent use of sepia.  I love everything about this shot.  It is elegant in it''s simplicity. Perfect angle to the capture.  Really awesome.  I''m giving this a perfect score.  It is well deserved.', '2005-07-25 13:21:49.000000', NULL, 1),
(1561602, 208489, 3569, '<td valign="top">nice instruments</td>', 'nice instruments', '2005-07-25 13:22:10.000000', NULL, 1),
(1561603, 205994, 15711, '<td valign="top">This stands out amidst all of the wooden planks of the challenge.  I love the shadow, the angle of the shot, the light, the color and the clarity is grear.  I praise your creativity. Thanks for a break from the norm on this one. I''m giving this one a 10</td>', 'This stands out amidst all of the wooden planks of the challenge.  I love the shadow, the angle of the shot, the light, the color and the clarity is grear.  I praise your creativity. Thanks for a break from the norm on this one. I''m giving this one a 10', '2005-07-25 13:22:17.000000', NULL, 1),
(1561604, 208526, 3569, '<td valign="top">wonderful use of color.</td>', 'wonderful use of color.', '2005-07-25 13:23:06.000000', NULL, 1),
(1561605, 208449, 15711, '<td valign="top">What a crisp clear photo.  I like his raised leg. The blue background offsets all the warm tones of the bird and the wood. Good job.</td>', 'What a crisp clear photo.  I like his raised leg. The blue background offsets all the warm tones of the bird and the wood. Good job.', '2005-07-25 13:23:10.000000', NULL, 1),
(1561609, 208446, 15711, '<td valign="top">Interesting texture and contrast. Most of the wood macros were sort of ho hum but this has some punch.   You chose an interesting angle to the shot so the leading lines go diagonally. I like that.</td>', 'Interesting texture and contrast. Most of the wood macros were sort of ho hum but this has some punch.   You chose an interesting angle to the shot so the leading lines go diagonally. I like that.', '2005-07-25 13:24:59.000000', NULL, 1),
(1561613, 208517, 15711, '<td valign="top">Interesting take.  Creative. I think I would like to see more of the negative space and perhaps the instrument off to one side or angled slightly for a tad more pizazz.  The detail is nicely shot.</td>', 'Interesting take.  Creative. I think I would like to see more of the negative space and perhaps the instrument off to one side or angled slightly for a tad more pizazz.  The detail is nicely shot.', '2005-07-25 13:26:20.000000', NULL, 1),
(1561616, 208637, 15711, '<td valign="top">As corny as this could be it''s actually quite clever. The tones of the background are a nice backdrop to the detailed rich dark tones and grain of the wood. The lighting is nicely done as well. I had to laugh though - it was a fun diversion from the seriousness of most of the others.</td>', 'As corny as this could be it''s actually quite clever. The tones of the background are a nice backdrop to the detailed rich dark tones and grain of the wood. The lighting is nicely done as well. I had to laugh though - it was a fun diversion from the seriousness of most of the others.', '2005-07-25 13:28:15.000000', NULL, 1),
(1561618, 208552, 15711, '<td valign="top">Good use of light and shadow.  The leading line effect is very present and works well. I like this one.</td>', 'Good use of light and shadow.  The leading line effect is very present and works well. I like this one.', '2005-07-25 13:28:45.000000', NULL, 1),
(1561620, 208406, 15711, '<td valign="top">Very clear capture.  I wish the background sky had more blue in it though.</td>', 'Very clear capture.  I wish the background sky had more blue in it though.', '2005-07-25 13:29:30.000000', NULL, 1),
(1561630, 208088, 7628, '<td valign="top">This is absolutely incredible - the color the glow.</td>', 'This is absolutely incredible - the color the glow.', '2005-07-25 13:34:38.000000', NULL, 1),
