INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1563117, 208554, 36619, '<td valign="top">the colors seem very un-natural and dark and even a little "splotchy"/uneven.  i think it works though, it''s very artsy. 9.</td>', 'the colors seem very un-natural and dark and even a little "splotchy"/uneven.  i think it works though, it''s very artsy. 9.', '2005-07-26 00:13:01.000000', NULL, 1),
(1563125, 208322, 36619, '<td valign="top">this shouldn''t be in this challenge, it should be on a some magazine cover somewhere. 10.</td>', 'this shouldn''t be in this challenge, it should be on a some magazine cover somewhere. 10.', '2005-07-26 00:17:34.000000', NULL, 1),
(1563128, 208530, 24511, '<td valign="top">Cute.  Reminds me of Easter and man made theme.  Very dark background makes whites on leaves stand out.  Fortunately the reflection of light on the varnished wood makes the main subject stand out as did the percentage of space used in the photo by the twigs.  I hated the eyeball button look.  I`ve never been a strong supporter of still life portraits.  First vote this challenge, I give it a four but will bump up if no better challengers.  Good luck.</td>', 'Cute.  Reminds me of Easter and man made theme.  Very dark background makes whites on leaves stand out.  Fortunately the reflection of light on the varnished wood makes the main subject stand out as did the percentage of space used in the photo by the twigs.  I hated the eyeball button look.  I`ve never been a strong supporter of still life portraits.  First vote this challenge, I give it a four but will bump up if no better challengers.  Good luck.', '2005-07-26 00:19:03.000000', NULL, 1),
(1563130, 207751, 36619, '<td valign="top">simple and clever. well done. 10.</td>', 'simple and clever. well done. 10.', '2005-07-26 00:19:08.000000', NULL, 1),
(1563137, 206616, 21714, '<td valign="top">You have made me feel for this fella!</td>', 'You have made me feel for this fella!', '2005-07-26 00:23:19.000000', NULL, 1),
(1563138, 208518, 36619, '<td valign="top">reminds me of a hobbbit home or something. has a lot of interesting elements.</td>', 'reminds me of a hobbbit home or something. has a lot of interesting elements.', '2005-07-26 00:23:50.000000', NULL, 1),
(1563143, 208558, 21714, '<td valign="top">I really can''t believe this! :)</td>', 'I really can''t believe this! :)', '2005-07-26 00:26:39.000000', NULL, 1),
(1563152, 208633, 24511, '<td valign="top">I just love a mystery.  What is this?  Looked like a bird/swan head carved on wood that was out of focus.  Maybe a broken chair back?  Enjoyed the old wood look that shows character.  Don`t like the blur effect.  I am wanting to scope the object in full detail close-up bit by bit or in full view.  OK 4 vote.</td>', 'I just love a mystery.  What is this?  Looked like a bird/swan head carved on wood that was out of focus.  Maybe a broken chair back?  Enjoyed the old wood look that shows character.  Don`t like the blur effect.  I am wanting to scope the object in full detail close-up bit by bit or in full view.  OK 4 vote.', '2005-07-26 00:30:53.000000', NULL, 1),
(1563167, 208670, 24511, '<td valign="top">Gargantuous angle on this shot played footsies with my imagination.  Very dull wood colors but perspective and lines blew me away.  I love the added activity above ground and the fact that the crop of this photo insists the massive presence of wood remains the days topic.  Crossing lines of forground shadow and upper white lines on ground near distant feet made my visual trip along the board less smooth.  Only my third vote but highest on this challenge.  Lucky seven award score.  Luck to you.</td>', 'Gargantuous angle on this shot played footsies with my imagination.  Very dull wood colors but perspective and lines blew me away.  I love the added activity above ground and the fact that the crop of this photo insists the massive presence of wood remains the days topic.  Crossing lines of forground shadow and upper white lines on ground near distant feet made my visual trip along the board less smooth.  Only my third vote but highest on this challenge.  Lucky seven award score.  Luck to you.', '2005-07-26 00:42:16.000000', NULL, 1),
(1563184, 208619, 29451, '<td valign="top">Beautiful - composition, colors, everything.</td>', 'Beautiful - composition, colors, everything.', '2005-07-26 00:50:13.000000', NULL, 1),
(1563186, 208683, 29451, '<td valign="top">Aww... This cat looks just like mine, white spot and all.  Great idea, nice composition, but I find it hard to see the dimension of the steps.  Perhaps a more angled shot would''ve helped.</td>', 'Aww... This cat looks just like mine, white spot and all.  Great idea, nice composition, but I find it hard to see the dimension of the steps.  Perhaps a more angled shot would''ve helped.', '2005-07-26 00:52:49.000000', NULL, 1),
(1563187, 206668, 24511, '<td valign="top">No way José.  The sky is fantastic and the color and play of light exquisite.  On its own I could easily score a 7 to 9 but for wood I leave you with a very weak 5 for shape and your promise that this is not a metal bridge.  Hasta la vista fellow photo challenger.</td>', 'No way José.  The sky is fantastic and the color and play of light exquisite.  On its own I could easily score a 7 to 9 but for wood I leave you with a very weak 5 for shape and your promise that this is not a metal bridge.  Hasta la vista fellow photo challenger.', '2005-07-26 00:52:49.000000', NULL, 1),
(1563193, 208159, 29451, '<td valign="top">Beautiful.  Nice lighting and composition.  Could do without the border, though.</td>', 'Beautiful.  Nice lighting and composition.  Could do without the border, though.', '2005-07-26 00:55:34.000000', NULL, 1),
(1563206, 208609, 24511, '<td valign="top">For such a nature filled composition your photo is very,  well,  organised by human toutch.  At first I thought wow what a great frame of vegetation.  Then I banged my vision against  the window leading me towards the bottom right corner.  Eventually the edge of the frame took me right out of the photo completely.  It doesn`t help that I was looking for wood here and there.  As I write these last few word I notice how the photo/mirror of the blond child fights for attention as much as the vegetation.  Loved the great division of shadow between window and vegetation.  Big four score screaming for more wood.  Thanks for the lovely photo.</td>', 'For such a nature filled composition your photo is very,  well,  organised by human toutch.  At first I thought wow what a great frame of vegetation.  Then I banged my vision against  the window leading me towards the bottom right corner.  Eventually the edge of the frame took me right out of the photo completely.  It doesn`t help that I was looking for wood here and there.  As I write these last few word I notice how the photo/mirror of the blond child fights for attention as much as the vegetation.  Loved the great division of shadow between window and vegetation.  Big four score screaming for more wood.  Thanks for the lovely photo.', '2005-07-26 01:09:14.000000', NULL, 1),
(1563218, 207998, 24511, '<td valign="top">Yeh!  I love ocean treasures.  This elephant cemetary of trees that border water and forest with the bereaving misty point of horizon can only mean one thing.  Bomb fire tonight until Dawn. Pebbles add terrific texture to whole.  Poor pixel sky prevented perfect score.  Great 8</td>', 'Yeh!  I love ocean treasures.  This elephant cemetary of trees that border water and forest with the bereaving misty point of horizon can only mean one thing.  Bomb fire tonight until Dawn. Pebbles add terrific texture to whole.  Poor pixel sky prevented perfect score.  Great 8', '2005-07-26 01:19:42.000000', NULL, 1),
(1563227, 208278, 24511, '<td valign="top">The water background looks sick.  The gold of the wood is wonderous.  Exellent choice of subject.  Angle very ordinairy.  Rope adds tension but somehow feel out of place.  I want to see more wood yet my battle is shared with the desire to zoom from the wood and see where the rope takes me.  The arrow point of the wood lines has my interest but I am left spashing the ugly water.  You really had me rocking on water with this photo.  6 for making me move so much.</td>', 'The water background looks sick.  The gold of the wood is wonderous.  Exellent choice of subject.  Angle very ordinairy.  Rope adds tension but somehow feel out of place.  I want to see more wood yet my battle is shared with the desire to zoom from the wood and see where the rope takes me.  The arrow point of the wood lines has my interest but I am left spashing the ugly water.  You really had me rocking on water with this photo.  6 for making me move so much.', '2005-07-26 01:35:19.000000', NULL, 1),
(1563247, 208501, 24511, '<td valign="top">I have to unload the washer right now and therfore have little time to comment.  I wish I had a board like yours to hand wash my none machine washables.  Send me yours and I will raise your score.  Just kidding.  I like the triad effect of your composition.  I do not like the pink.  (I hate pink in gereral ).  I am very interested in the printing on the wood.  Good luck 5 score.</td>', 'I have to unload the washer right now and therfore have little time to comment.  I wish I had a board like yours to hand wash my none machine washables.  Send me yours and I will raise your score.  Just kidding.  I like the triad effect of your composition.  I do not like the pink.  (I hate pink in gereral ).  I am very interested in the printing on the wood.  Good luck 5 score.', '2005-07-26 01:48:09.000000', NULL, 1),
(1563250, 208149, 24511, '<td valign="top">9 for people score but only 4 this challenge as subtle wood beam very elusive.  The child basically steals the shot.</td>', '9 for people score but only 4 this challenge as subtle wood beam very elusive.  The child basically steals the shot.', '2005-07-26 01:50:57.000000', NULL, 1),
(1563254, 207918, 24511, '<td valign="top">Fuzzy vision was never my peg of choice but I do like the angle and mostly the lighting of your shot.  You have my most potential in this challenge award.  7 score</td>', 'Fuzzy vision was never my peg of choice but I do like the angle and mostly the lighting of your shot.  You have my most potential in this challenge award.  7 score', '2005-07-26 01:54:19.000000', NULL, 1),
(1563256, 208145, 24511, '<td valign="top">Whakie weird wood neat but I would have a different background.  Nice crisp clear image with little shadow does not pull me into the shot.  Very ordinairy OK photo.  5 score.</td>', 'Whakie weird wood neat but I would have a different background.  Nice crisp clear image with little shadow does not pull me into the shot.  Very ordinairy OK photo.  5 score.', '2005-07-26 01:57:54.000000', NULL, 1),
(1563263, 205728, 24511, '<td valign="top">Odd that these wooden buckets seem more like clay pots.  The painted surface or lack of visible wooden design would make me knock on to see if it is indeed wood.  Lovely perspective.  Very monochromatic type leaves me indifferent.  Lettering  and lighting my favorite part of photo.  Top right shapes a slight distraction.  High 5 vote.</td>', 'Odd that these wooden buckets seem more like clay pots.  The painted surface or lack of visible wooden design would make me knock on to see if it is indeed wood.  Lovely perspective.  Very monochromatic type leaves me indifferent.  Lettering  and lighting my favorite part of photo.  Top right shapes a slight distraction.  High 5 vote.', '2005-07-26 02:03:19.000000', NULL, 1),
(1563270, 208435, 24511, '<td valign="top">Poloriser wowing blue color sky with great woody lines.  A quick 9 vote.  Would have scored much higher with less blue above and ground bellow and less centered... ok, ok... so I`m a terrible back seat photographer manabe.  Good luck.</td>', 'Poloriser wowing blue color sky with great woody lines.  A quick 9 vote.  Would have scored much higher with less blue above and ground bellow and less centered... ok, ok... so I`m a terrible back seat photographer manabe.  Good luck.', '2005-07-26 02:07:31.000000', NULL, 1),
(1563276, 207612, 24511, '<td valign="top">Ten, ten, ten and straight into my favorites.  Thank you very, very much.  You have no idea how great a photographic eye you have.</td>', 'Ten, ten, ten and straight into my favorites.  Thank you very, very much.  You have no idea how great a photographic eye you have.', '2005-07-26 02:10:55.000000', NULL, 1),
(1563363, 207794, 27164, '<td valign="top">Wow, great use of leading lines, the shadows on the wood provide great interest, there''s plenty of DOF, and the view is magnificent.  My only slight complaint is that the sky seems blown, but that is minor and doesn''t detract much from the overal effect.</td>', 'Wow, great use of leading lines, the shadows on the wood provide great interest, there''s plenty of DOF, and the view is magnificent.  My only slight complaint is that the sky seems blown, but that is minor and doesn''t detract much from the overal effect.', '2005-07-26 03:29:28.000000', NULL, 1),
(1563366, 208665, 37409, '<td valign="top">With those being carvings I expected more sharp edges. It seems soft.</td>', 'With those being carvings I expected more sharp edges. It seems soft.', '2005-07-26 03:32:01.000000', NULL, 1),
(1563367, 208621, 27164, '<td valign="top">Whoa, great contrast and color, the composition is excellent as well.  I think you''ll probablly get hammered for over-processing though.</td>', 'Whoa, great contrast and color, the composition is excellent as well.  I think you''ll probablly get hammered for over-processing though.', '2005-07-26 03:32:10.000000', NULL, 1),
(1563370, 208501, 37409, '<td valign="top">This out of focus and the lighting has given a sort of blue tinge to the shot. I suspect a flash.</td>', 'This out of focus and the lighting has given a sort of blue tinge to the shot. I suspect a flash.', '2005-07-26 03:32:53.000000', NULL, 1),
(1563371, 208632, 37409, '<td valign="top">The windows distracts from the composition of the image</td>', 'The windows distracts from the composition of the image', '2005-07-26 03:33:16.000000', NULL, 1),
(1563372, 206266, 27164, '<td valign="top">Whoa, this photo is absolutely beautiful.  It''s interesting that you chose to include the pillar on the right, but I think it really adds to the photo.  I expect this one to make top ten.</td>', 'Whoa, this photo is absolutely beautiful.  It''s interesting that you chose to include the pillar on the right, but I think it really adds to the photo.  I expect this one to make top ten.', '2005-07-26 03:34:08.000000', NULL, 1),
(1563374, 208189, 37409, '<td valign="top">The road below has competely blown out this shot.</td>', 'The road below has competely blown out this shot.', '2005-07-26 03:34:27.000000', NULL, 1),
(1563375, 207878, 37409, '<td valign="top">I would have maybe gotten a lower angle on this but over all good. Also maybe would crop out some of the wave splashing as it distracts. When I see the calmness of the lakes, and the solitude of the little pier I feel peaceful until that wave comes crashing in.</td>', 'I would have maybe gotten a lower angle on this but over all good. Also maybe would crop out some of the wave splashing as it distracts. When I see the calmness of the lakes, and the solitude of the little pier I feel peaceful until that wave comes crashing in.', '2005-07-26 03:35:58.000000', NULL, 1),
(1563377, 208592, 37409, '<td valign="top">Nice gradient</td>', 'Nice gradient', '2005-07-26 03:36:32.000000', NULL, 1),
(1563379, 207372, 37409, '<td valign="top">Nice shot, sharp, but not very "creativity is key"<br/>Dont be offended, still a superbly sharp image.</td>', 'Nice shot, sharp, but not very "creativity is key"Dont be offended, still a superbly sharp image.', '2005-07-26 03:37:40.000000', NULL, 1),
(1563380, 207754, 37409, '<td valign="top">Lighting is bad. Takes away from the shot</td>', 'Lighting is bad. Takes away from the shot', '2005-07-26 03:38:01.000000', NULL, 1),
(1563381, 207791, 37409, '<td valign="top">I would have tried a fill flash here. I want to see all those nice timbers forming the structure.</td>', 'I would have tried a fill flash here. I want to see all those nice timbers forming the structure.', '2005-07-26 03:38:32.000000', NULL, 1),
(1563382, 207901, 27164, '<td valign="top">Great DOF and use of leading lines.  The grain, to me, looks fine, but I bet you''ll get hammered even though it''s probably intentional.  Good luck.</td>', 'Great DOF and use of leading lines.  The grain, to me, looks fine, but I bet you''ll get hammered even though it''s probably intentional.  Good luck.', '2005-07-26 03:39:33.000000', NULL, 1),
(1563387, 207607, 27164, '<td valign="top">WOW!  This photo is absolutely STUNNING!  The colors look great, the compostion, lighting, and focus are spot-on, and the subject is interesting.  What a great photo, I hope this one picks up a ribbon.</td>', 'WOW!  This photo is absolutely STUNNING!  The colors look great, the compostion, lighting, and focus are spot-on, and the subject is interesting.  What a great photo, I hope this one picks up a ribbon.', '2005-07-26 03:42:11.000000', NULL, 1),
(1563391, 208380, 37409, '<td valign="top">Nice and sharp</td>', 'Nice and sharp', '2005-07-26 03:45:07.000000', NULL, 1),
(1563393, 208366, 37409, '<td valign="top">Contrast seems very harsh</td>', 'Contrast seems very harsh', '2005-07-26 03:45:29.000000', NULL, 1),
(1563394, 208600, 37409, '<td valign="top">Out of focus</td>', 'Out of focus', '2005-07-26 03:45:41.000000', NULL, 1),
(1563395, 207638, 37409, '<td valign="top">The skewers seem soft</td>', 'The skewers seem soft', '2005-07-26 03:46:11.000000', NULL, 1),
(1563396, 207149, 37409, '<td valign="top">I would have cropped the field out</td>', 'I would have cropped the field out', '2005-07-26 03:46:43.000000', NULL, 1),
(1563402, 208515, 37409, '<td valign="top">The paper background is very distracting</td>', 'The paper background is very distracting', '2005-07-26 03:54:14.000000', NULL, 1),
(1563405, 208654, 28742, '<td valign="top">Hilarious! Ahhh, the bizarre things in nature.</td>', 'Hilarious! Ahhh, the bizarre things in nature.', '2005-07-26 03:54:33.000000', NULL, 1),
(1563408, 208526, 37409, '<td valign="top">Nice sharp photo, great color.<br/>Not  a very creative idea</td>', 'Nice sharp photo, great color.Not  a very creative idea', '2005-07-26 03:55:36.000000', NULL, 1),
(1563413, 208543, 27164, '<td valign="top">Wonderful landscape, however the posts to me don''t make up the main subject of the photo, so IMHO it''s a bit of a stretch to meet the challenge.</td>', 'Wonderful landscape, however the posts to me don''t make up the main subject of the photo, so IMHO it''s a bit of a stretch to meet the challenge.', '2005-07-26 04:00:38.000000', NULL, 1),
(1563417, 208520, 37409, '<td valign="top">Great worn wood. I enjoy the old paint giving the colors of blue and yellow.<br/>Much more creative than the masses of pencils, blocks, trees, houses, and woddys.<br/>Thanks for using the creative side of your brain.</td>', 'Great worn wood. I enjoy the old paint giving the colors of blue and yellow.Much more creative than the masses of pencils, blocks, trees, houses, and woddys.Thanks for using the creative side of your brain.', '2005-07-26 04:07:57.000000', NULL, 1),
(1563418, 208624, 37409, '<td valign="top">Cool shot.. Finally, in the challenge full of blah someone did something creative. Love the choice of lens here.</td>', 'Cool shot.. Finally, in the challenge full of blah someone did something creative. Love the choice of lens here.', '2005-07-26 04:09:17.000000', NULL, 1),
(1563419, 208428, 37409, '<td valign="top">That blue tarp ruins what would is a nice composition</td>', 'That blue tarp ruins what would is a nice composition', '2005-07-26 04:09:54.000000', NULL, 1),
(1563420, 208439, 37409, '<td valign="top">Too much border.. way too much.. Nice composition though.</td>', 'Too much border.. way too much.. Nice composition though.', '2005-07-26 04:11:36.000000', NULL, 1),
