(1569545, 207612, 33560, '<td valign="top">The composition and framing are inspired; the lighting is exquisite; the very deep DOF is perfect.  Super</td>', 'The composition and framing are inspired; the lighting is exquisite; the very deep DOF is perfect.  Super', '2005-07-28 10:52:05.000000', NULL, 1),
