INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1570967, 207659, 3669, '<td valign="top">That is definately a lot of wood.  Could do without the fence.</td>', 'That is definately a lot of wood.  Could do without the fence.', '2005-07-28 23:44:10.000000', NULL, 1),
(1570974, 206616, 3669, '<td valign="top">A very creative shot.  Very emotive for a "Woody" photo.  I really like it.  Definately a 10, in my book.</td>', 'A very creative shot.  Very emotive for a "Woody" photo.  I really like it.  Definately a 10, in my book.', '2005-07-28 23:46:15.000000', NULL, 1),
(1570978, 208624, 22537, '<td valign="top">Very cool.  Good luck!</td>', 'Very cool.  Good luck!', '2005-07-28 23:47:04.000000', NULL, 1),
(1570982, 208681, 3669, '<td valign="top">Very interesting photo.  I like the lighting and shadows.</td>', 'Very interesting photo.  I like the lighting and shadows.', '2005-07-28 23:48:09.000000', NULL, 1),
(1570983, 208153, 3669, '<td valign="top">Nice lines and detail.  Good job.</td>', 'Nice lines and detail.  Good job.', '2005-07-28 23:48:44.000000', NULL, 1),
(1570986, 208523, 3669, '<td valign="top">Nice lines and detail.</td>', 'Nice lines and detail.', '2005-07-28 23:49:51.000000', NULL, 1),
(1570990, 207767, 3669, '<td valign="top">I like the effect of the water splash.   I would have liked to see more detail in the wood.  Too dark.</td>', 'I like the effect of the water splash.   I would have liked to see more detail in the wood.  Too dark.', '2005-07-28 23:51:33.000000', NULL, 1),
(1570991, 208375, 8377, '<td valign="top">I really like the dream-like feel to this. The colors in it are just awesome.</td>', 'I really like the dream-like feel to this. The colors in it are just awesome.', '2005-07-28 23:52:01.000000', NULL, 1),
(1570994, 208022, 3669, '<td valign="top">Nice lines and detail.  Lighting perfect.</td>', 'Nice lines and detail.  Lighting perfect.', '2005-07-28 23:52:49.000000', NULL, 1),
(1570998, 207844, 3669, '<td valign="top">Lighting seems just a little on the harsh side.  Otherwise great lines and detail.</td>', 'Lighting seems just a little on the harsh side.  Otherwise great lines and detail.', '2005-07-28 23:53:43.000000', NULL, 1),
(1571000, 207774, 22537, '<td valign="top">This is an excellent image though I would have selected only the windmill for the partial desat. Reason is that the trees are not weathered. 6</td>', 'This is an excellent image though I would have selected only the windmill for the partial desat. Reason is that the trees are not weathered. 6', '2005-07-28 23:54:20.000000', NULL, 1),
(1571001, 208022, 22537, '<td valign="top">Very clean and sharp.  Good luck!</td>', 'Very clean and sharp.  Good luck!', '2005-07-28 23:54:59.000000', NULL, 1),
(1571002, 207290, 3669, '<td valign="top">Love the mysterious"ness" of the picture.  Interesting lighting and effects.  Hope you are scoring well in this challenge because this is a fantastic picture, IMO</td>', 'Love the mysterious"ness" of the picture.  Interesting lighting and effects.  Hope you are scoring well in this challenge because this is a fantastic picture, IMO', '2005-07-28 23:55:15.000000', NULL, 1),
(1571003, 207896, 3669, '<td valign="top">Creative composition.  I love the detail.  Lighting couldn''t be more perfect.  Good job.</td>', 'Creative composition.  I love the detail.  Lighting couldn''t be more perfect.  Good job.', '2005-07-28 23:56:33.000000', NULL, 1),
(1571008, 206824, 3669, '<td valign="top">Dizzying perspective.  Lovely lighting.</td>', 'Dizzying perspective.  Lovely lighting.', '2005-07-29 00:00:49.000000', NULL, 1),
(1571011, 208462, 3669, '<td valign="top">I like the rustic"ness" of the wood and the leaves look nice in the photo.  Lighting is good.  Shows great detail.  Good job.</td>', 'I like the rustic"ness" of the wood and the leaves look nice in the photo.  Lighting is good.  Shows great detail.  Good job.', '2005-07-29 00:02:28.000000', NULL, 1),
(1571018, 208304, 3669, '<td valign="top">Very nice capture.  Lighting couldn''t be any more perfect.  Great focus.  Shows nice detail.</td>', 'Very nice capture.  Lighting couldn''t be any more perfect.  Great focus.  Shows nice detail.', '2005-07-29 00:03:44.000000', NULL, 1),
(1571025, 208518, 3669, '<td valign="top">I like the dreamy"ness" of the photo.  Looks like the home of an animal in a fairy tale book.  Lighting is perfect and shows great detail.</td>', 'I like the dreamy"ness" of the photo.  Looks like the home of an animal in a fairy tale book.  Lighting is perfect and shows great detail.', '2005-07-29 00:06:15.000000', NULL, 1),
(1571046, 208519, 3669, '<td valign="top">Nicely done.  Shows great detail.</td>', 'Nicely done.  Shows great detail.', '2005-07-29 00:17:46.000000', NULL, 1),
(1571053, 208407, 3669, '<td valign="top">Shows great detail.  I like the rustic"ness".  the lighting appears a little harsh on the wood, though.</td>', 'Shows great detail.  I like the rustic"ness".  the lighting appears a little harsh on the wood, though.', '2005-07-29 00:20:01.000000', NULL, 1),
(1571056, 208498, 3669, '<td valign="top">Shows nice detail.  Crop seems a bit tight, though.</td>', 'Shows nice detail.  Crop seems a bit tight, though.', '2005-07-29 00:21:24.000000', NULL, 1),
(1571060, 208592, 3669, '<td valign="top">Nice lighting and interesting perspective.</td>', 'Nice lighting and interesting perspective.', '2005-07-29 00:22:51.000000', NULL, 1),
(1571064, 208373, 3669, '<td valign="top">Interesting lighting.  Appears a tad harsh at the top right.  Also seems just a tad OOF.</td>', 'Interesting lighting.  Appears a tad harsh at the top right.  Also seems just a tad OOF.', '2005-07-29 00:24:25.000000', NULL, 1),
(1571070, 206168, 3669, '<td valign="top">Lighting seems a bit harsh on the right, especially on the metal part of the pencils causing the distracting reflection.  Perhaps shining the light on the other side would have been more appropriate for these subjects.</td>', 'Lighting seems a bit harsh on the right, especially on the metal part of the pencils causing the distracting reflection.  Perhaps shining the light on the other side would have been more appropriate for these subjects.', '2005-07-29 00:26:49.000000', NULL, 1),
(1571095, 208636, 3669, '<td valign="top">I really like the rustic"ness" of this picture.  I seems, though, that it needs to be rotated a couple of degrees to the left to make the top edge parallel to the top of the window.  I think this picture would also look good in a light sepia tone.</td>', 'I really like the rustic"ness" of this picture.  I seems, though, that it needs to be rotated a couple of degrees to the left to make the top edge parallel to the top of the window.  I think this picture would also look good in a light sepia tone.', '2005-07-29 00:41:09.000000', NULL, 1),
(1571097, 208600, 3669, '<td valign="top">Definately meets challenge and is a nice perspective of the piano.  Just could use more focus and less noise.</td>', 'Definately meets challenge and is a nice perspective of the piano.  Just could use more focus and less noise.', '2005-07-29 00:42:45.000000', NULL, 1),
(1571105, 208212, 3669, '<td valign="top">Nice perspective on such a simple subject as clothes pins in their natural setting.  My only complaint...picture just seems a tad dark.  Perhaps a little boost in contrast would work.</td>', 'Nice perspective on such a simple subject as clothes pins in their natural setting.  My only complaint...picture just seems a tad dark.  Perhaps a little boost in contrast would work.', '2005-07-29 00:46:42.000000', NULL, 1),
(1571109, 206668, 3669, '<td valign="top">The sunset is pretty and nicely captured, but in this challenge, I think that getting a little closer to your subject would have been appropriate.</td>', 'The sunset is pretty and nicely captured, but in this challenge, I think that getting a little closer to your subject would have been appropriate.', '2005-07-29 00:48:34.000000', NULL, 1),
(1571114, 207063, 3669, '<td valign="top">Nice DOF.  I like the perspective.  My only complaint...I think angling yourself in taking the picture to get more door and less white would have been nice.</td>', 'Nice DOF.  I like the perspective.  My only complaint...I think angling yourself in taking the picture to get more door and less white would have been nice.', '2005-07-29 00:50:16.000000', NULL, 1),
(1571121, 208144, 3669, '<td valign="top">Lots of wood...definately meets challenge.  Good detail.  I think you could have gotten away with a little tighter crop.</td>', 'Lots of wood...definately meets challenge.  Good detail.  I think you could have gotten away with a little tighter crop.', '2005-07-29 00:53:14.000000', NULL, 1),
(1571129, 206818, 3669, '<td valign="top">Looks like this would have been a nice picture.  Wish it were bigger so as to see better detail, therefore easier to critique</td>', 'Looks like this would have been a nice picture.  Wish it were bigger so as to see better detail, therefore easier to critique', '2005-07-29 00:55:44.000000', NULL, 1),
(1571132, 207827, 3669, '<td valign="top">Nice lighting, however, I wish that there could have more sun light on the chair.  I like the rustic"ness".  Interesting perspective.</td>', 'Nice lighting, however, I wish that there could have more sun light on the chair.  I like the rustic"ness".  Interesting perspective.', '2005-07-29 00:57:20.000000', NULL, 1),
(1571135, 206144, 3669, '<td valign="top">Have to admit that this is an origional perspective.  I don''t think I"m all that crazy about it, though.  I do like the light and shadows and the wood grain detail in the flooring.</td>', 'Have to admit that this is an origional perspective.  I don''t think I"m all that crazy about it, though.  I do like the light and shadows and the wood grain detail in the flooring.', '2005-07-29 00:59:48.000000', NULL, 1),
(1571138, 207800, 3669, '<td valign="top">Nice lighting and interesting detail.</td>', 'Nice lighting and interesting detail.', '2005-07-29 01:01:16.000000', NULL, 1),
(1571143, 208335, 3669, '<td valign="top">Did you use the dodge tool on the bench?  I find that the light halo around the edges is a bit distracting.  Otherwise, great subject for the challenge and I like the angle at which it was taken with the foilage in the background.</td>', 'Did you use the dodge tool on the bench?  I find that the light halo around the edges is a bit distracting.  Otherwise, great subject for the challenge and I like the angle at which it was taken with the foilage in the background.', '2005-07-29 01:04:06.000000', NULL, 1),
(1571145, 206665, 3669, '<td valign="top">Awww...very sad.  Emotive...good creativity.</td>', 'Awww...very sad.  Emotive...good creativity.', '2005-07-29 01:06:05.000000', NULL, 1),
(1571152, 206824, 19831, '<td valign="top">An interesting subject and the perspective is pretty cool. IMO, the lighting in this case is weakening the presentation a little. There seems to be a loss of a lot of strong detail in the darkness at right. And the flare of the sun on the right edge seems to be distracting. Perhaps the same shot taken at a different time of day, with the light coming in from a different angle could make a difference?</td>', 'An interesting subject and the perspective is pretty cool. IMO, the lighting in this case is weakening the presentation a little. There seems to be a loss of a lot of strong detail in the darkness at right. And the flare of the sun on the right edge seems to be distracting. Perhaps the same shot taken at a different time of day, with the light coming in from a different angle could make a difference?', '2005-07-29 01:10:29.000000', NULL, 1),
(1571388, 208632, 40807, '<td valign="top">I love this photograph...it captures a moment that I wish I were in.</td>', 'I love this photograph...it captures a moment that I wish I were in.', '2005-07-29 04:29:16.000000', NULL, 1),
(1571402, 207638, 22748, '<td valign="top">Awesome!!! I guess the title might be a pun on skewed distribution? Great patterns and I love how the vertical lines in the foreground are complemented by the diagonal lines of the background. Perfect!!</td>', 'Awesome!!! I guess the title might be a pun on skewed distribution? Great patterns and I love how the vertical lines in the foreground are complemented by the diagonal lines of the background. Perfect!!', '2005-07-29 04:52:43.000000', NULL, 1),
